import vine from '@vinejs/vine'
import { MAX_IMPORT_SIZE_MB } from '#constants/csv_transfer'

/**
 * A product CSV upload. `importId` (generated by the browser) tags the
 * progress messages so the dialog that started the import can follow it.
 */
export const adminProductsImportStoreValidator = vine.create({
  file: vine.file({ size: `${MAX_IMPORT_SIZE_MB}mb`, extnames: ['csv'] }),
  importId: vine.string().trim().uuid().optional(),
})
